/**
 * Admin sign-in (W5, plan 1.5): one password, generated by the owner's setup script.
 *
 * Password
 * - The setup script stores hex(HMAC-SHA256(APP_SECRET, password)) as the ADMIN_PASSWORD_HASH
 *   secret (a 20-character random password, about 115 bits, so a fast keyed hash is enough).
 * - A password the owner changes in the admin is stored in settings.admin_password_hash, which then
 *   overrides the secret. Because a person picks that one, it is stretched: PBKDF2-SHA256 with a
 *   random salt, peppered with APP_SECRET ("pbkdf2-sha256$<iterations>$<salt hex>$<hash hex>").
 * - Every comparison is constant time (crypto.ts timingSafeEqual).
 *
 * Guessing limits (config.ts RATE_LIMITS)
 * - admin_login_ip: 5 tries per 15 minutes per IP, counted before the password is checked.
 * - admin_login_global: 20 wrong passwords per day from anywhere. Past that, the login form locks
 *   for ADMIN_LOCKOUT (1 hour) for everyone, and every further wrong password locks it again. A
 *   signed-in admin is not affected: the lock only stops new sign-ins.
 *
 * Sessions (admin_sessions)
 * - Cookie __Host-fbc_admin: 32 random bytes, base64url. HttpOnly, Secure, SameSite=Strict,
 *   Path=/, no Domain (the __Host- prefix makes browsers enforce that), so it never reaches a
 *   course subdomain and is never sent on a cross-site request.
 * - D1 stores only sha256Hex(token). A session ends after 12 hours idle (ADMIN_IDLE_TTL) or 7 days
 *   in all (ADMIN_ABSOLUTE_TTL), on logout, or when the password changes.
 */
import { ADMIN_ABSOLUTE_TTL, ADMIN_COOKIE, ADMIN_IDLE_TTL, ADMIN_LOCKOUT, ADMIN_PASSWORD_MIN_LENGTH, requireSecret } from "../config.ts";
import { hmacSha256Hex, randomHex, randomToken, sha256Hex, timingSafeEqual } from "../crypto.ts";
import { auditStatement } from "../db/audit.ts";
import type { Db } from "../db/d1.ts";
import { ValidationError } from "../db/errors.ts";
import { getSetting, setSettingStatement } from "../db/settings.ts";
import { batch } from "../db/tx.ts";
import type { Env } from "../env.ts";
import { clientIp } from "../http.ts";
import { ipSubject } from "../guard.ts";
import { hit } from "../ratelimit.ts";

/** The audit log's actor for everything done in the admin. */
export const ADMIN_ACTOR = "admin";

/** Workers cap PBKDF2 at 100,000 iterations. */
export const PBKDF2_ITERATIONS = 100_000;
const PBKDF2_PREFIX = "pbkdf2-sha256";
/** Longest password accepted (a bound on hashing work per request). */
export const ADMIN_PASSWORD_MAX_LENGTH = 200;
/** last_seen_at is refreshed at most this often. */
export const ADMIN_TOUCH_INTERVAL = 300;
/** The rate_limits row that holds the login lock (cleaned up by W7's daily job once it expires). */
export const LOCKOUT_BUCKET = "admin_lockout:global";

const encoder = new TextEncoder();

function toHex(bytes: Uint8Array): string {
  let out = "";
  for (const byte of bytes) out += byte.toString(16).padStart(2, "0");
  return out;
}

function fromHex(hex: string): Uint8Array {
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  return out;
}

async function pbkdf2Hex(appSecret: string, password: string, saltHex: string, iterations: number): Promise<string> {
  // The pepper: without APP_SECRET a copy of the database alone can't be brute-forced.
  const peppered = await hmacSha256Hex(appSecret, password);
  const key = await crypto.subtle.importKey("raw", encoder.encode(peppered), "PBKDF2", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits(
    { name: "PBKDF2", hash: "SHA-256", salt: fromHex(saltHex), iterations },
    key,
    256,
  );
  return toHex(new Uint8Array(bits));
}

/** The stored form of a password the admin chose (settings.admin_password_hash). */
export async function hashAdminPassword(appSecret: string, password: string, iterations = PBKDF2_ITERATIONS): Promise<string> {
  const salt = randomHex(16);
  return `${PBKDF2_PREFIX}$${iterations}$${salt}$${await pbkdf2Hex(appSecret, password, salt, iterations)}`;
}

/** Checks a password against either stored form. Unknown forms never match. */
export async function verifyAdminPassword(appSecret: string, password: string, stored: string): Promise<boolean> {
  if (stored.startsWith(`${PBKDF2_PREFIX}$`)) {
    const parts = stored.split("$");
    if (parts.length !== 4) return false;
    const iterations = Number(parts[1]);
    const salt = parts[2]!;
    const expected = parts[3]!;
    if (!Number.isSafeInteger(iterations) || iterations < 1_000 || iterations > PBKDF2_ITERATIONS) return false;
    if (!/^[0-9a-f]{32}$/.test(salt) || !/^[0-9a-f]{64}$/.test(expected)) return false;
    return timingSafeEqual(await pbkdf2Hex(appSecret, password, salt, iterations), expected);
  }
  if (/^[0-9a-fA-F]{64}$/.test(stored)) {
    return timingSafeEqual(await hmacSha256Hex(appSecret, password), stored.toLowerCase());
  }
  return false;
}

/** The hash in force: settings (after a change in the admin) wins over the setup secret. */
async function storedPasswordHash(env: Env): Promise<{ hash: string; source: "settings" | "secret" }> {
  const fromSettings = await getSetting(env.DB, "admin_password_hash");
  if (typeof fromSettings === "string" && fromSettings.length > 0) return { hash: fromSettings, source: "settings" };
  return { hash: requireSecret(env, "ADMIN_PASSWORD_HASH", 64), source: "secret" };
}

/** True when `password` is the admin password. Throws ConfigError before the owner runs setup. */
export async function checkAdminPassword(env: Env, password: string): Promise<boolean> {
  const appSecret = requireSecret(env, "APP_SECRET", 32);
  const { hash } = await storedPasswordHash(env);
  return verifyAdminPassword(appSecret, password, hash);
}

/** A password from a request body: text, 1 to 200 characters (no trimming: spaces count). */
export function passwordField(value: unknown, field: string): string {
  if (typeof value !== "string" || value.length < 1) throw new ValidationError(field, "Enter the password.", "required");
  if (value.length > ADMIN_PASSWORD_MAX_LENGTH) throw new ValidationError(field, "That password is too long.");
  return value;
}

/** A new password: 14 to 200 characters, not all the same character, at least 6 different ones. */
export function newPasswordField(value: unknown, field = "next"): string {
  const password = passwordField(value, field);
  if (password.length < ADMIN_PASSWORD_MIN_LENGTH) {
    throw new ValidationError(field, `Use at least ${ADMIN_PASSWORD_MIN_LENGTH} characters.`);
  }
  if (password.trim() !== password) throw new ValidationError(field, "The password can't start or end with a space.");
  if (new Set(password).size < 6) throw new ValidationError(field, "Use a less repetitive password.");
  return password;
}

// ---------------------------------------------------------------- login lock

/** Unix time the login lock ends, or null when sign-in is open. */
export async function lockedUntil(db: Db, now: number): Promise<number | null> {
  const row = await db
    .prepare("SELECT expires_at FROM rate_limits WHERE bucket = ? AND expires_at > ?")
    .bind(LOCKOUT_BUCKET, now)
    .first<{ expires_at: number }>();
  return row ? row.expires_at : null;
}

async function lock(db: Db, now: number): Promise<number> {
  const until = now + ADMIN_LOCKOUT;
  await db
    .prepare(
      "INSERT INTO rate_limits (bucket, count, expires_at) VALUES (?, 1, ?) " +
        "ON CONFLICT (bucket) DO UPDATE SET count = count + 1, expires_at = excluded.expires_at",
    )
    .bind(LOCKOUT_BUCKET, until)
    .run();
  return until;
}

// ---------------------------------------------------------------- sessions

export interface AdminSession {
  id: number;
  /** When this session ends unless it is used again (idle) or at the latest (absolute). */
  expiresAt: number;
}

/** Set-Cookie for a new session. Max-Age is the absolute lifetime; idle expiry is checked in D1. */
export function adminCookie(token: string): string {
  return `${ADMIN_COOKIE}=${token}; Path=/; Max-Age=${ADMIN_ABSOLUTE_TTL}; HttpOnly; Secure; SameSite=Strict`;
}

/** Set-Cookie that removes the session cookie. */
export function clearAdminCookie(): string {
  return `${ADMIN_COOKIE}=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Strict`;
}

/** The admin cookie's token from a request, or null when absent or malformed. */
export function adminToken(request: Request): string | null {
  const header = request.headers.get("Cookie") ?? "";
  for (const part of header.split(";")) {
    const i = part.indexOf("=");
    if (i === -1) continue;
    if (part.slice(0, i).trim() !== ADMIN_COOKIE) continue;
    const value = part.slice(i + 1).trim();
    return /^[A-Za-z0-9_-]{43}$/.test(value) ? value : null;
  }
  return null;
}

function sessionExpiry(row: { expires_at: number; last_seen_at: number }): number {
  return Math.min(row.expires_at, row.last_seen_at + ADMIN_IDLE_TTL);
}

/** Creates a session. Returns its Set-Cookie value. */
export async function createAdminSession(db: Db, request: Request, now: number): Promise<{ cookie: string; session: AdminSession }> {
  const token = randomToken(32);
  const userAgent = (request.headers.get("User-Agent") ?? "").slice(0, 400) || null;
  const ip = clientIp(request).slice(0, 64);
  const result = await db
    .prepare(
      "INSERT INTO admin_sessions (token_hash, created_at, last_seen_at, expires_at, ip, user_agent) VALUES (?, ?, ?, ?, ?, ?)",
    )
    .bind(await sha256Hex(token), now, now, now + ADMIN_ABSOLUTE_TTL, ip, userAgent)
    .run();
  const id = result.meta.last_row_id;
  return { cookie: adminCookie(token), session: { id, expiresAt: Math.min(now + ADMIN_ABSOLUTE_TTL, now + ADMIN_IDLE_TTL) } };
}

/** The request's valid admin session, or null. Refreshes last_seen_at at most every 5 minutes. */
export async function readAdminSession(db: Db, request: Request, now: number): Promise<AdminSession | null> {
  const token = adminToken(request);
  if (!token) return null;
  const row = await db
    .prepare(
      "SELECT id, last_seen_at, expires_at FROM admin_sessions " +
        "WHERE token_hash = ? AND revoked_at IS NULL AND expires_at > ? AND last_seen_at > ?",
    )
    .bind(await sha256Hex(token), now, now - ADMIN_IDLE_TTL)
    .first<{ id: number; last_seen_at: number; expires_at: number }>();
  if (!row) return null;
  if (now - row.last_seen_at >= ADMIN_TOUCH_INTERVAL) {
    await db.prepare("UPDATE admin_sessions SET last_seen_at = ? WHERE id = ?").bind(now, row.id).run();
    row.last_seen_at = now;
  }
  return { id: row.id, expiresAt: sessionExpiry(row) };
}

/** Ends one session (logout). */
export async function revokeAdminSession(db: Db, id: number, now: number): Promise<void> {
  await db.prepare("UPDATE admin_sessions SET revoked_at = ? WHERE id = ? AND revoked_at IS NULL").bind(now, id).run();
}

// ---------------------------------------------------------------- the flows

export type LoginResult =
  | { ok: true; cookie: string; session: AdminSession }
  | { ok: false; status: 429; code: "admin_locked" | "rate_limited"; retryAfter: number }
  | { ok: false; status: 401; code: "wrong_password" };

/**
 * Checks a sign-in attempt and, when the password is right, starts a session. Order matters: the
 * lock and the per-IP limit are checked before any password work, so a locked form costs nothing.
 */
export async function login(env: Env, request: Request, rawPassword: unknown, now: number): Promise<LoginResult> {
  const db = env.DB;
  const until = await lockedUntil(db, now);
  if (until !== null) return { ok: false, status: 429, code: "admin_locked", retryAfter: until - now };

  const ip = clientIp(request);
  // Counted per /64 for IPv6 (guard.ts ipSubject): one phone or home can't rotate past the limit.
  const perIp = await hit(db, "admin_login_ip", ipSubject(request), { now });
  if (!perIp.allowed) return { ok: false, status: 429, code: "rate_limited", retryAfter: perIp.retryAfter };

  const password = passwordField(rawPassword, "password");
  if (!(await checkAdminPassword(env, password))) {
    const global = await hit(db, "admin_login_global", "global", { now });
    const lockedTill = global.allowed ? null : await lock(db, now);
    await auditStatement(db, {
      actor: ADMIN_ACTOR,
      action: "admin.login_failed",
      entity: "admin",
      data: { ip: ip.slice(0, 64), locked: lockedTill !== null },
      now,
    }).run();
    return { ok: false, status: 401, code: "wrong_password" };
  }

  const { cookie, session } = await createAdminSession(db, request, now);
  await batch(db, [
    auditStatement(db, { actor: ADMIN_ACTOR, action: "admin.login", entity: "admin", entityId: session.id, data: { ip: ip.slice(0, 64) }, now }),
    // Housekeeping: sessions that ended over 30 days ago.
    db.prepare("DELETE FROM admin_sessions WHERE expires_at < ? OR revoked_at < ?").bind(now - 30 * 86_400, now - 30 * 86_400),
  ]);
  return { ok: true, cookie, session };
}

/**
 * Changes the admin password: checks the current one (rate limited like a sign-in), stores the new
 * one stretched in settings, ends every admin session and starts a fresh one for this browser.
 */
export async function changePassword(
  env: Env,
  request: Request,
  input: { current: unknown; next: unknown },
  now: number,
): Promise<LoginResult> {
  const db = env.DB;
  // Counted per /64 for IPv6 (guard.ts ipSubject): one phone or home can't rotate past the limit.
  const perIp = await hit(db, "admin_login_ip", ipSubject(request), { now });
  if (!perIp.allowed) return { ok: false, status: 429, code: "rate_limited", retryAfter: perIp.retryAfter };

  const current = passwordField(input.current, "current");
  const next = newPasswordField(input.next, "next");
  if (!(await checkAdminPassword(env, current))) {
    await auditStatement(db, { actor: ADMIN_ACTOR, action: "admin.password_change_failed", entity: "admin", now }).run();
    return { ok: false, status: 401, code: "wrong_password" };
  }
  if (next === current) throw new ValidationError("next", "The new password must be different.");

  const appSecret = requireSecret(env, "APP_SECRET", 32);
  const hash = await hashAdminPassword(appSecret, next);
  await batch(db, [
    setSettingStatement(db, "admin_password_hash", hash, now),
    db.prepare("UPDATE admin_sessions SET revoked_at = ? WHERE revoked_at IS NULL").bind(now),
    auditStatement(db, { actor: ADMIN_ACTOR, action: "admin.password_change", entity: "admin", now }),
  ]);
  const { cookie, session } = await createAdminSession(db, request, now);
  return { ok: true, cookie, session };
}
